// 대전외국인학교 (대전 유성구) - automatic high-school package (auto-school track, user decision 2026-10-23). Generated by djforeign-local-builder
// from OSM way/356718314 + AWS Terrain Tiles: every school building destructible (grammar models, floors estimated where OSM has none),
// a baked ground (one terrain mesh with two drawn colour maps), fence / gates / stands / goals, trees and the extruded neighbourhood fading
// into the haze. Local only (registry public: false). Do not edit by hand - rerun the generator.
import { WORLD_UNITS_PER_METER, GEO_ORIGIN, DJFOREIGN_PLACEMENTS, DJFOREIGN_BUILDING_BASE, DJFOREIGN_HEIGHT_GRIDS, DJFOREIGN_HEIGHT_RANGE_M, DJFOREIGN_ENV_IDS, DJFOREIGN_DISPLAY, DJFOREIGN_START_FRAME, DJFOREIGN_OVERVIEW_AZIMUTH, DJFOREIGN_CAMERA, DJFOREIGN_PROVENANCE } from './data.js';
import { DJFOREIGN_FOOTPRINTS } from './footprints.js';
import { DJFOREIGN_PROTECTED } from './protected.js';

const MODEL_IDS = Object.freeze(DJFOREIGN_PLACEMENTS.map(p => p.id));
const asset = file => new URL(`../../../assets/campuses/djforeign/${file}`, import.meta.url).href;
const HAZE = DJFOREIGN_DISPLAY.haze, FADE = DJFOREIGN_DISPLAY.fade;

export const DJFOREIGN = Object.freeze({
  id: 'djforeign',
  meta: Object.freeze({ school: '대전외국인학교', campus: '대전', short: '대전외국인학교', modelNoun: '대전외국인학교' }),
  geo: Object.freeze({ origin: GEO_ORIGIN, worldUnitsPerMeter: WORLD_UNITS_PER_METER }),
  placements: DJFOREIGN_PLACEMENTS,
  approvedCount: DJFOREIGN_PLACEMENTS.length,
  additionalCount: 0,
  coreIds: MODEL_IDS,
  startBuildingId: 'athletics' || MODEL_IDS[0],
  // camera picked by scripts/auto-school/build.mjs from the measured occlusion (azimuths in radians, elevations in degrees, src/camera.js angles)
  view: Object.freeze({ get startFrame() { return (globalThis.innerWidth || 1280) < 600 ? {"min":[20,-18,-8],"max":[66,8,12],"azimuth":-1.15,"elevationDegrees":30} : {"min":[8,-14,-12],"max":[60,10,14],"azimuth":-0.5}; }, overviewAzimuth: DJFOREIGN_OVERVIEW_AZIMUTH }),
  camera: DJFOREIGN_CAMERA,
  models: Object.freeze({
    manifests: Object.freeze([
      Object.freeze({ url: asset('manifest.json'), expectedIds: MODEL_IDS }),
      Object.freeze({ url: asset('environment.json'), expectedIds: DJFOREIGN_ENV_IDS }),
    ]),
    proceduralIds: Object.freeze([]),
    createProceduralSource: () => { throw new Error('No procedural buildings in this campus'); },
    enhanceFacade: () => ({ stats: {}, dispose() {} }),
  }),
  terrain: Object.freeze({ heightGrids: DJFOREIGN_HEIGHT_GRIDS, buildingBase: DJFOREIGN_BUILDING_BASE, source: DJFOREIGN_PROVENANCE.terrain }),
  environment: Object.freeze({ provenance: DJFOREIGN_PROVENANCE, sourceNote: 'OSM ground surfaces and surroundings (© OpenStreetMap contributors, ODbL); heights, floors and planting estimated automatically' }),
  ground: Object.freeze({
    baked: Object.freeze({ envIds: DJFOREIGN_ENV_IDS, castShadow: Object.freeze([]),
      fade: Object.freeze({ centre_m: Object.freeze([...FADE.centreEN]), near_m: FADE.r0_m, far_m: FADE.r1_m, linear: FADE.linearShare, colour: HAZE }), playMargin_m: 30,
      source: 'djforeign-local-builder baked ground' }),
  }),
  protected: Object.freeze({ models: DJFOREIGN_PROTECTED }),
  hazardTape: Object.freeze({ footprints: DJFOREIGN_FOOTPRINTS, maxStep_m: .3 }),   // round 8: a tape quad spanning more than 0.45 m of height (wall / cap edge, ramp) is left out instead of folding up
  scene: Object.freeze({
    background: HAZE, fog: Object.freeze({ color: HAZE, near: 500, far: 1400 }),
    hemisphere: Object.freeze({ sky: '#ffffff', ground: '#7d8a78', intensity: 1.35 }),
    sun: Object.freeze({ color: '#fff4e2', intensity: 3.1, position: Object.freeze([-110, 165, 140]), shadowSpan: 200 }),
    floor: Object.freeze({ color: '#c9cbc8', hidden: true, y: DJFOREIGN_HEIGHT_RANGE_M[0] * WORLD_UNITS_PER_METER - .3 }),
  }),
});
export default DJFOREIGN;
